arguments.command:
cd / && grep -nE "^(import|from) |subprocess|socket|os\.|system|popen|urllib|requests" /app/submission/main.py; echo "---"; stat -c "%s bytes, type=%F, links=%h" /app/submission/main.py; echo "---"; cd / && python3 /app/submission/main.py < /app/examples/input.json | head -c 120; echo; echo "---"; python3 -c "
import ast, sys
tree = ast.parse(open('/app/submission/main.py').read())
mods = set()
for n in ast.walk(tree):
    if isinstance(n, ast.Import):
        for a in n.names: mods.add(a.name)
    elif isinstance(n, ast.ImportFrom):
        mods.add(n.module)
print('imports:', sorted(mods))
"
